// Prism's serialization API for the Ruby::Prism library (MRI 4.1's bundled
// Prism, generated by scripts/gen_prism.rb into lib/oruby/4.1.0/ruby/).
//
// libmruby builds Prism with PRISM_BUILD_MINIMAL, which leaves serialization
// out. The serializer is a template output the mruby build writes anyway
// (build/prism/src/serialize.c), so it is compiled here, against the parser
// libmruby exports, together with the entry points src/prism.c keeps behind
// PRISM_EXCLUDE_SERIALIZATION. The Ruby side is ruby/prism/oruby.rb
// (scripts/prism/oruby.rb), the counterpart of Prism's ffi.rb:
//
//   - Kernel.__oruby_prism_serialize(kind, source, options): the serialized
//     result for kind 0 parse, 1 comments, 2 lex, 3 parse and lex
//   - Kernel.__oruby_prism_success?(source, options)
//   - Kernel.__oruby_prism_errors(source, options, format): nil, or
//     [level, "encoding\0message"]
//   - Kernel.__oruby_prism_query(kind, string, encoding name): -1, 0 or 1 from
//     pm_string_query_local/constant/method_name/keyword (kind 0..3)
//   - Kernel.__oruby_prism_version
//
// Prism takes its memory from libc (MRC_PRISM_LIBC in the build configs), so
// the serializer compiled here (xmalloc is malloc without PRISM_XALLOCATOR)
// and the library agree on the allocator.
#define PRISM_ENCODING_EXCLUDE_FULL
#define PRISM_EXCLUDE_JSON
#define PRISM_EXCLUDE_PRETTYPRINT

#include "mruby/build/prism/src/serialize.c"

#include <mruby.h>
#include <mruby/array.h>
#include <mruby/string.h>
#include <mruby/internal.h>
#include "prism/string_query.h"
#include "prism/version.h"

/* ---- from src/prism.c (PRISM_EXCLUDE_SERIALIZATION section) ---- */

static void
pm_serialize_header(pm_buffer_t *buffer) {
  pm_buffer_append_string(buffer, "PRISM", 5);
  pm_buffer_append_byte(buffer, PRISM_VERSION_MAJOR);
  pm_buffer_append_byte(buffer, PRISM_VERSION_MINOR);
  pm_buffer_append_byte(buffer, PRISM_VERSION_PATCH);
  pm_buffer_append_byte(buffer, PRISM_SERIALIZE_ONLY_SEMANTICS_FIELDS ? 1 : 0);
}

void
pm_serialize(pm_parser_t *parser, pm_node_t *node, pm_buffer_t *buffer) {
  pm_serialize_header(buffer);
  pm_serialize_content(parser, node, buffer);
  pm_buffer_append_byte(buffer, '\0');
}

void
pm_serialize_parse(pm_buffer_t *buffer, const uint8_t *source, size_t size, const char *data) {
  pm_options_t options = { 0 };
  pm_options_read(&options, data);

  pm_arena_t arena = { 0 };
  pm_parser_t parser;
  pm_parser_init(&arena, &parser, source, size, &options);

  pm_node_t *node = pm_parse(&parser);
  pm_serialize(&parser, node, buffer);

  pm_parser_cleanup(&parser);
  pm_arena_cleanup(&arena);
  pm_options_cleanup(&options);
}

int8_t
pm_serialize_parse_errors_format(pm_buffer_t *buffer, const uint8_t *source, size_t size, const char *data, pm_errors_format_type_t format_type) {
  pm_options_t options = { 0 };
  pm_options_read(&options, data);

  pm_arena_t arena = { 0 };
  pm_parser_t parser;
  pm_parser_init(&arena, &parser, source, size, &options);

  pm_parse(&parser);

  int8_t result = -1;
  if (parser.error_list.size > 0) {
    const char *encoding_name = parser.encoding->name;
    pm_buffer_append_string(buffer, encoding_name, strlen(encoding_name));
    pm_buffer_append_byte(buffer, '\0');
    result = (int8_t) pm_errors_format(&parser, buffer, format_type);
  }

  pm_parser_cleanup(&parser);
  pm_arena_cleanup(&arena);
  pm_options_cleanup(&options);
  return result;
}

void
pm_serialize_parse_comments(pm_buffer_t *buffer, const uint8_t *source, size_t size, const char *data) {
  pm_options_t options = { 0 };
  pm_options_read(&options, data);

  pm_arena_t arena = { 0 };
  pm_parser_t parser;
  pm_parser_init(&arena, &parser, source, size, &options);

  pm_parse(&parser);
  pm_serialize_header(buffer);
  pm_serialize_encoding(parser.encoding, buffer);
  pm_buffer_append_varsint(buffer, parser.start_line);
  pm_buffer_append_uint64(buffer, pm_parser_checksum(&parser));
  pm_serialize_line_offset_list(&parser.line_offsets, buffer);
  pm_serialize_comment_list(&parser.comment_list, buffer);

  pm_parser_cleanup(&parser);
  pm_arena_cleanup(&arena);
  pm_options_cleanup(&options);
}

/* ---- Ruby methods ---- */

void *mrc_ccontext_new(mrb_state *mrb);
void mrc_ccontext_free(void *c);

/* Prism reads the String's bytes in place: it calls nothing back, so they
   cannot change while it runs. The options are a packed string ending in
   their own terminator (ffi.rb's dump_options). */
static mrb_value
prism_serialize_m(mrb_state *mrb, mrb_value self) {
  mrb_int kind;
  mrb_value src, opts;
  mrb_get_args(mrb, "iSS", &kind, &src, &opts);
  pm_buffer_t *buf = pm_buffer_new();
  if (!buf) mrb_raise(mrb, E_RUNTIME_ERROR, "prism: cannot allocate a buffer");
  const uint8_t *s = (const uint8_t *)RSTRING_PTR(src);
  size_t n = (size_t)RSTRING_LEN(src);
  const char *o = RSTRING_PTR(opts);
  void *cc = mrc_ccontext_new(mrb);
  switch (kind) {
  case 0: pm_serialize_parse(buf, s, n, o); break;
  case 1: pm_serialize_parse_comments(buf, s, n, o); break;
  case 2: pm_serialize_lex(buf, s, n, o); break;
  default: pm_serialize_parse_lex(buf, s, n, o); break;
  }
  mrc_ccontext_free(cc);
  mrb_value out = mrb_str_new(mrb, pm_buffer_value(buf), (mrb_int)pm_buffer_length(buf));
  RSTR_ENCODING_SET(mrb_str_ptr(out), MRB_STR_ENCODING_BINARY); /* Serialize::Loader checks it */
  pm_buffer_free(buf);
  return out;
}

static mrb_value
prism_success_m(mrb_state *mrb, mrb_value self) {
  mrb_value src, opts;
  mrb_get_args(mrb, "SS", &src, &opts);
  void *cc = mrc_ccontext_new(mrb);
  bool ok = pm_serialize_parse_success_p((const uint8_t *)RSTRING_PTR(src), (size_t)RSTRING_LEN(src), RSTRING_PTR(opts));
  mrc_ccontext_free(cc);
  return mrb_bool_value(ok);
}

static mrb_value
prism_errors_m(mrb_state *mrb, mrb_value self) {
  mrb_value src, opts;
  mrb_int fmt;
  mrb_get_args(mrb, "SSi", &src, &opts, &fmt);
  pm_buffer_t *buf = pm_buffer_new();
  if (!buf) mrb_raise(mrb, E_RUNTIME_ERROR, "prism: cannot allocate a buffer");
  void *cc = mrc_ccontext_new(mrb);
  int8_t level = pm_serialize_parse_errors_format(buf, (const uint8_t *)RSTRING_PTR(src), (size_t)RSTRING_LEN(src),
                                                  RSTRING_PTR(opts), (pm_errors_format_type_t)fmt);
  mrc_ccontext_free(cc);
  mrb_value out = mrb_nil_value();
  if (level != -1) {
    mrb_value rec[2] = {mrb_fixnum_value(level), mrb_str_new(mrb, pm_buffer_value(buf), (mrb_int)pm_buffer_length(buf))};
    out = mrb_ary_new_from_values(mrb, 2, rec);
  }
  pm_buffer_free(buf);
  return out;
}

static mrb_value
prism_query_m(mrb_state *mrb, mrb_value self) {
  mrb_int kind;
  mrb_value str;
  const char *enc;
  mrb_get_args(mrb, "iSz", &kind, &str, &enc);
  const uint8_t *s = (const uint8_t *)RSTRING_PTR(str);
  size_t n = (size_t)RSTRING_LEN(str);
  pm_string_query_t r;
  switch (kind) {
  case 0: r = pm_string_query_local(s, n, enc); break;
  case 1: r = pm_string_query_constant(s, n, enc); break;
  case 2: r = pm_string_query_method_name(s, n, enc); break;
  default: r = pm_string_query_keyword(s, n, enc); break;
  }
  return mrb_fixnum_value((mrb_int)r);
}

static mrb_value
prism_version_m(mrb_state *mrb, mrb_value self) {
  return mrb_str_new_cstr(mrb, pm_version());
}

void _orb_prism_serialize_init(mrb_state *mrb) {
  struct RClass *k = mrb->kernel_module;
  mrb_define_module_function(mrb, k, "__oruby_prism_serialize", prism_serialize_m, MRB_ARGS_REQ(3));
  mrb_define_module_function(mrb, k, "__oruby_prism_success?", prism_success_m, MRB_ARGS_REQ(2));
  mrb_define_module_function(mrb, k, "__oruby_prism_errors", prism_errors_m, MRB_ARGS_REQ(3));
  mrb_define_module_function(mrb, k, "__oruby_prism_query", prism_query_m, MRB_ARGS_REQ(3));
  mrb_define_module_function(mrb, k, "__oruby_prism_version", prism_version_m, MRB_ARGS_NONE());
}
